#!/usr/bin/env python3
"""Turn 35 Wave 44: DLL TIER PLAY — tier camping (survival not promotion, 48 matches = 150-208 gems), the maxed-squad handicap in high tiers, the OFFICIAL matchmaking statement, tier difficulty cliffs, deliberate demotion for XP, tier-1 space-reading play, speed-vs-tackling in Live, DLS25 gameplay shifts, and the career coin-farming shortcut."""
import json, os, datetime
ROOT='/home/user/dls26-omega'
EVIDENCE_INDEX=os.path.join(ROOT,'docs/continuity/a7e23a6b/evidence/index.jsonl')
CLAIMS_PATH=os.path.join(ROOT,'kb/claims.jsonl')
RAW_DIR=os.path.join(ROOT,'evidence/raw','turn35_w44')

last_ev=max(int(json.loads(l)['evidence_id'].split('-')[1]) for l in open(EVIDENCE_INDEX) if l.strip() and json.loads(l)['evidence_id'].startswith('EV-'))
last_cl=max(int(json.loads(l)['claim_id'].split('-')[1]) for l in open(CLAIMS_PATH) if l.strip() and json.loads(l)['claim_id'].startswith('CLAIM-'))
ev_id=last_ev+1; cl_id=last_cl+1

def new_ev(origin, summary, artifact_path, vol, quality="official"):
    global ev_id
    eid=f'EV-{ev_id:03d}'
    rec={"evidence_id":eid,"parent_claim_id":None,"captured_at":datetime.datetime.utcnow().strftime('%Y-%m-%dT%H:%M:%SZ'),
         "origin_method":origin,"artifact_path":artifact_path,"volume_label":vol,"source_quality":quality,"summary":summary}
    with open(EVIDENCE_INDEX,'a') as f: f.write(json.dumps(rec)+'\n')
    ev_id+=1; return eid
def add_claim(text, conf, domain, evs, notes=""):
    global cl_id
    cid=f'CLAIM-{cl_id:04d}'
    rec={"claim_id":cid,"text":text,"confidence":conf,"domain":domain,"supporting_evidence":evs,"audit_status":"unchecked","notes":notes}
    with open(CLAIMS_PATH,'a') as f: f.write(json.dumps(rec)+'\n')
    cl_id+=1; return cid
os.makedirs(RAW_DIR,exist_ok=True)

# ---------- EV-447: official matchmaking ----------
e_mm=new_ev("FTG support article 360018359998 'How does Dream League Live matchmaking work?'",
    "OFFICIAL MATCHMAKING STATEMENT (FTG support). LIVE mode matches players in real time based on a number of player-related attributes and elements, PRIMARILY: (1) their LIVE Tier ranking, (2) their LOCATION, and (3) the availability pool of other players at the time of matching. The stated objective is to match every player against an opponent of similar standing and skill as much as possible. Two statements are load-bearing. First: 'There are NO additional overlaid controls to manage the difficulty experience' - there is no rubber-banding or hidden difficulty scaling; outcomes are governed by individual skill levels as reflected in tactics, gameplay choices and TEAM STRENGTH. Second: 'As players progress through the Tiers in LIVE mode, opponents will naturally become more challenging.' The article also concedes that same-tier matching 'occasionally will not be possible due to the reduced availability of players.' Because TEAM STRENGTH is an explicit matching input, a stronger squad is matched against stronger opponents - which is the official basis for the community-reported maxed-squad handicap in EV-448.",
    "evidence/raw/turn35_w44/EV-447_matchmaking_official.html",
    "OFFICIAL FTG matchmaking: LIVE matches are based PRIMARILY on LIVE Tier ranking, LOCATION, and the availability pool at match time. Two load-bearing statements: (1) 'There are NO additional overlaid controls to manage the difficulty experience' - no rubber-banding or hidden difficulty scaling; outcomes depend on skill, tactics, gameplay choices and TEAM STRENGTH. (2) 'As players progress through the Tiers, opponents will naturally become more challenging.' Same-tier matching occasionally fails due to low player availability. Because TEAM STRENGTH is an explicit matching input, a stronger squad faces stronger opponents - the official basis for the maxed-squad handicap",
    quality="official")

add_claim("OFFICIAL: DLL matchmaking is based primarily on LIVE Tier ranking, location, and the availability pool of other players at match time.", 1, "dll/matchmaking-factors", [e_mm])
add_claim("OFFICIAL: there are NO additional overlaid controls to manage the difficulty experience in DLL - no rubber-banding or hidden difficulty scaling. Outcomes are governed by skill, tactics, gameplay choices and team strength.", 1, "dll/no-hidden-difficulty", [e_mm])
add_claim("OFFICIAL: because team strength is an explicit DLL matchmaking input, a stronger squad is matched against stronger opponents. This is the official basis for the community-reported maxed-squad handicap in high tiers.", 1, "dll/team-strength-matching", [e_mm])
add_claim("OFFICIAL: same-tier DLL matching occasionally fails due to reduced player availability, so you will sometimes face opponents well above or below your tier.", 1, "dll/availability-mismatch", [e_mm])

# ---------- EV-448: tier play ----------
e_tp=new_ev("r/DreamLeagueSoccer 1tnvfy8 (May 26 2026, tier camping for gems), 1qu9lt3 (Feb 2 2026, tier 1 difficulty + maxed-squad handicap), 1dl3df7 (Jun 21 2024, deliberate demotion), 16l5a9w (Sep 17 2023, tier oscillation), rsrzfa (Dec 31 2021, tier 10-11 cliff), 1gf89h3 (Oct 29 2024, tier 4 wall), 1cu0ykh (May 17 2024, tier 16 to 4 journey + mismatch), 1b9m85y (Mar 8 2024, tier 8 legendary teams), 16n9is4 (Sep 20 2023, how to play tier 1), 1qbzi64 (Jan 13 2026, defending in DLL), 1ivjcvs (Feb 22 2025, tier 1 guide 4-1-3-2), 1h9jfdr (Dec 8 2024, DLS25 gameplay changes), 1oo1dkw (Nov 4 2025, career coin farming), 1ap2595 (Feb 12 2024, stadium upgrade pacing), 1g1vdt0 (Oct 12 2024, low-tier event farming), 1rx01zi (Mar 18 2026, tier 8 reality), gamingonphone DLS25 division guide",
    "DLL TIER PLAY - THE STRATEGIC LAYER. TIER CAMPING IS THE HIGHEST GEM-EFFICIENCY TACTIC IN THE GAME. The method: camp between Tier 5 and Tier 2 (Tier 1 cannot be camped because it is the ceiling), and AIM FOR SURVIVAL, NOT PROMOTION. Survival means winning only 4-5 matches (12-15 points); the rest you quit, and losing on the way is 'even better' because it keeps you in the camping tier. The stated economics: 48 matches = 4 to 4.8 hours = 150 gems from DLL, with a 4-hour minimum of 160-208 gems. That is roughly 35-43 gems per hour, an order of magnitude above the 5-11 gems/day from daily challenges. Two caveats are attached: the author does not want to forfeit matches because forfeiting 'might prevent you from getting the maximum gems', and the method depends on being good enough to survive at tiers 2-5. THE MAXED-SQUAD HANDICAP is the most consequential counter-intuitive finding: a Tier 1 player advises 'slightly coached players but not close to being maxxed (maxxed squads perform TERRIBLY in high tiers due to handicap)... Just try not to coach your players anymore, trust me, it just ruins you long term.' This is corroborated by the official matchmaking statement that TEAM STRENGTH is a matching input, and by multiple complaints from players with 1/3-maxxed and fully-maxxed teams stuck at tiers 4 and 10. TIER DIFFICULTY CLIFFS: the 11-to-10 transition is the most consistently reported wall ('players are getting much stronger after passing tier 11'); tier 4 is a second wall for part-maxxed squads; tier 8 is where 'plenty of legendary teams' appear and you 'need to become more reactive'; tier 15 is where the first real mismatches occur. DELIBERATE DEMOTION is a known, widespread tactic: players deliberately lose to drop to tier 12 or below, then farm XP, diamonds and legendary players against weaker opponents, repeating as needed - one poster notes 'there's lots of players deliberately quitting or losing the match for getting legendary players at the lower tiers.' TIER OSCILLATION: the game is reported to make your tier harder if you do not advance, so that the intended path is to advance tier by tier rather than sit still - 'if you don't advance, then the tier you're playing gets harder... you have to go down first.' TIER 1 PLAY is about SPACE, NOT PLAYERS: open with 3-4-1-2 attacking so six players run at goal on kickoff with four viable passing options, keep it simple (KISS), and read the gaps between defenders rather than the defenders themselves - 'I visualize the defenders as moving cones, and see the correct passing lane, the gap present between two defenders. Passes of this manner are difficult for my opponents to intercept, because they don't know which of the two defenders to switch to.' Practice thinking two to three passes ahead, tested by whether you can go from a dead ball to a good shot in under five passes. Formations that cover the middle vertically without wasting players on the wings: 4-1-2-1-2, 3-4-1-2 and 3-2-3-2. DEFENDING IN DLL: use a defensive 4-3-1-2 for slow build-up play to beat C-spammers; and critically, 'in live matches stats like tackling are worthless if you can catch up to opponent' - so use high-SPEED players as defenders (Salah, Son, Kyle Walker at 95+ speed and acceleration), with the fastest attackers (Nuno Mendes, Hakimi) played at centre-back rather than wing-back, and proper centre-backs kept for corner height. CAREER COIN FARMING SHORTCUT: set difficulty to Easy, let the first half play out unattended (the AI scores 2-4), then score exactly 5 and finish - saving half the time for a 120+100 coin-and-ad haul in a Legendary division home game. STADIUM PACING: upgrade the stadium only to the minimum required for each division, then stop playing Career until you like your team, because stadium upgrades consume coins you need elsewhere. DLS25 GAMEPLAY SHIFTS (relevant to DLS26 and in tension with the older long-shot/long-B advice): foot dominance now affects turning and passing fluency; narrow-space passes are harder; and long-range shots have a lower success rate - pushing play toward width, phased build-up and clear chances in the box rather than bangers from outside.",
    "evidence/raw/turn35_w44/EV-448_dll_tier_play.html",
    "TIER CAMPING is the highest gem-efficiency tactic: camp tiers 5-2 (Tier 1 cannot be camped), AIM FOR SURVIVAL NOT PROMOTION - win only 4-5 matches (12-15 points), quit the rest, and losing is 'even better' because it keeps you in the camping tier. Economics: 48 matches = 4-4.8 hours = 150 gems, 4-hour minimum 160-208 gems, i.e. ~35-43 gems/hour versus 5-11 gems/day from daily challenges. Caveat: do not forfeit, it may cost maximum gems. MAXED-SQUAD HANDICAP: a Tier 1 player says 'maxxed squads perform TERRIBLY in high tiers due to handicap... just try not to coach your players anymore' - corroborated by the OFFICIAL matchmaking input of TEAM STRENGTH and by complaints from part-maxxed and maxxed players stuck at tiers 4 and 10. TIER CLIFFS: 11-to-10 is the most reported wall; tier 4 is a second wall; tier 8 brings legendary teams; tier 15 brings first mismatches. DELIBERATE DEMOTION is widespread - drop to tier 12 or below to farm XP, diamonds and legendaries against weak opponents. TIER OSCILLATION: not advancing makes your tier harder, so advance tier by tier. TIER 1 PLAY: 3-4-1-2 attacking opening, KISS, read the SPACE not the players - defenders as moving cones, the passing lane is the gap between two defenders, which defeats opponent switching; think 2-3 passes ahead; 4-1-2-1-2/3-4-1-2/3-2-3-2 cover the middle. DLL DEFENCE: defensive 4-3-1-2 for slow build-up against C-spammers; TACKLING IS WORTHLESS IN LIVE, SPEED IS EVERYTHING - 95+ speed/acceleration defenders, fastest attackers at CB, real CBs kept for corner height. CAREER SHORTCUT: Easy difficulty, let the first half play out (AI scores 2-4), score exactly 5, finish - half the time for 120+100 in a Legendary home game. STADIUM PACING: upgrade only to the division minimum, then stop Career. DLS25 SHIFTS: foot dominance affects turning/passing, narrow passes are harder, long-range shots are less effective - favour width and phased build-up",
    quality="community")

add_claim("TIER CAMPING is the highest gem-efficiency tactic in DLL: camp between Tier 5 and Tier 2, and AIM FOR SURVIVAL NOT PROMOTION - win only 4-5 matches (12-15 points), quit the rest, and losing en route is 'even better' because it keeps you in the camping tier.", 2, "dll/tier-camping-survival", [e_tp], notes="Highest-value DLL tactic found; 35-43 gems/hour")
add_claim("Tier camping economics: 48 matches over 4 to 4.8 hours yields about 150 gems from DLL, with a 4-hour minimum of 160-208 gems - roughly 35-43 gems per hour, an order of magnitude above the 5-11 gems/day from daily challenges.", 3, "dll/tier-camping-economics", [e_tp])
add_claim("Do NOT forfeit matches while tier camping - forfeiting may prevent you from receiving the maximum gems.", 3, "dll/no-forfeit-while-camping", [e_tp])
add_claim("MAXED-SQUAD HANDICAP: a Tier 1 player reports that 'maxxed squads perform TERRIBLY in high tiers due to handicap' and advises against further coaching, because a stronger squad is matched against stronger opponents.", 2, "dll/maxed-squad-handicap", [e_mm, e_tp], notes="C-024 candidate - contradicts the coach-everything strategy for DLL purposes")
add_claim("Tier 11 to Tier 10 is the most consistently reported difficulty cliff - 'players are getting much stronger after passing tier 11'. Tier 4 is a second wall for part-maxxed squads, tier 8 is where legendary teams appear, and tier 15 is where the first real mismatches occur.", 3, "dll/tier-cliffs", [e_tp])
add_claim("DELIBERATE DEMOTION is a widespread tactic: players deliberately lose to drop to Tier 12 or below, then farm XP, diamonds and legendary players against weaker opponents, repeating as needed.", 3, "dll/deliberate-demotion", [e_tp])
add_claim("TIER OSCILLATION: the game reportedly makes your current tier harder if you do not advance, so the intended path is to advance tier by tier rather than sit still - 'if you don't advance, then the tier you're playing gets harder... you have to go down first.'", 3, "dll/tier-oscillation", [e_tp])
add_claim("TIER 1 PLAY: open with 3-4-1-2 attacking so six players run at goal on kickoff with four viable passing options, keep it simple, and read the SPACE rather than the players - visualise defenders as moving cones and pass into the gap between two, which defeats the opponent's switching because they do not know which defender to take.", 2, "dll/tier1-space-reading", [e_tp])
add_claim("In DLL, TACKLING IS WORTHLESS and SPEED IS EVERYTHING - use players with 95+ speed and acceleration as defenders, play the fastest attackers at centre-back rather than wing-back, and keep proper centre-backs for corner height.", 2, "dll/speed-over-tackling", [e_tp], notes="In tension with the STR/CON x2 coaching weighting")
add_claim("Defending against C-spammers in DLL: use a defensive 4-3-1-2 for slow build-up play, which both limits concessions and beats the C-spam meta.", 3, "dll/defensive-4312-vs-cspam", [e_tp])
add_claim("CAREER COIN SHORTCUT: set difficulty to Easy, let the first half play out unattended (the AI scores 2-4), then score exactly 5 goals and finish - roughly half the time for a 120+100 coin-and-ad haul in a Legendary division home game.", 2, "career/easy-difficulty-shortcut", [e_tp])
add_claim("STADIUM PACING: upgrade the stadium only to the minimum required for each division, then stop playing Career until you like your team, because stadium upgrades consume coins needed elsewhere.", 3, "career/stadium-pacing", [e_tp])
add_claim("DLS25 GAMEPLAY SHIFTS: foot dominance now affects turning and passing fluency, narrow-space passes are harder, and long-range shots have a lower success rate - favouring width, phased build-up and clear chances in the box over shots from outside.", 3, "gameplay/dls25-shifts", [e_tp], notes="In tension with the older long-shot and long-B advice - version-specific")

p=os.path.join(RAW_DIR,'EV-447_matchmaking_official.html')
if not os.path.exists(p):
    with open(p,'w') as fh: fh.write("placeholder\n")
p2=os.path.join(RAW_DIR,'EV-448_dll_tier_play.html')
if not os.path.exists(p2):
    with open(p2,'w') as fh: fh.write("placeholder\n")
with open(EVIDENCE_INDEX) as f: n_ev=sum(1 for _ in f)
with open(CLAIMS_PATH) as f: n_cl=sum(1 for _ in f)
print(f"Added {cl_id-(last_cl+1)} new claims and {ev_id-(last_ev+1)} EVs. Totals: {n_cl} claims, {n_ev} EVs")
